local FishHookMaker = {}
local PRODUCTS = {
    iron_fishhook = { name = "Železni ribiška kavka", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ribiška kavka za ribištvvo." },
    bronze_fishhook = { name = "Bronast ribiška kavka", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ribiška kavka za ribištvvo." },
    silver_fishhook = { name = "Srebrn ribiška kavka", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn ribiška kavka za ribištvvo." },
    gilded_fishhook = { name = "Pozlačen ribiška kavka", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen ribiška kavka za ribištvvo." },
    jewel_set_fishhook = { name = "Draguljast ribiška kavka", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast ribiška kavka za ribištvvo." },
    royal_sovereign_fishhook = { name = "Kraljevski suveren ribiška kavka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren ribiška kavka z biseri za krono." },
}
local BUILDINGS = {
    fishhook_workshop = { name = "Fishhook delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    fishhook_house = { name = "Fishhook hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_fishhook_atelier = { name = "Mojstrski fishhook atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_fishhook_palace = { name = "Suverena fishhook palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
FishHookMaker.ironStock = 18; FishHookMaker.bronzeStock = 14; FishHookMaker.woodStock = 8; FishHookMaker.leatherStock = 8; FishHookMaker.silverStock = 8; FishHookMaker.goldStock = 6; FishHookMaker.jewelStock = 4; FishHookMaker.pearlStock = 4
FishHookMaker.productStock = {}; FishHookMaker.buildings = {}; FishHookMaker.maker = nil; FishHookMaker.activeMaking = {}; FishHookMaker.totalProducts = 0; FishHookMaker.dayTimer = 0
function FishHookMaker.init() FishHookMaker.ironStock=18; FishHookMaker.bronzeStock=14; FishHookMaker.woodStock=8; FishHookMaker.leatherStock=8; FishHookMaker.silverStock=8; FishHookMaker.goldStock=6; FishHookMaker.jewelStock=4; FishHookMaker.pearlStock=4; FishHookMaker.productStock={}; FishHookMaker.buildings={}; FishHookMaker.maker=nil; FishHookMaker.activeMaking={}; FishHookMaker.totalProducts=0; FishHookMaker.dayTimer=0; print("[FishHookMaker] Royal Fish Hook Maker System initialized (6 products, 4 buildings)") end
function FishHookMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FishHookMaker.maker={name=n or ("Kavkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kavkar najet: %s (spretnost: %d)",FishHookMaker.maker.name,s),"success") end; return true end
function FishHookMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FishHookMaker.build(id) local ok,e=FishHookMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FishHookMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FishHookMaker.getQualityBonus() local b=0; for _,bd in ipairs(FishHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FishHookMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and FishHookMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and FishHookMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and FishHookMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FishHookMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FishHookMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FishHookMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FishHookMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FishHookMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FishHookMaker.buildings==0 then return false,"Potrebna kavkarska delavnica" end; if not FishHookMaker.maker then return false,"Potreben kavkar" end; return true end
function FishHookMaker.make(pt,qty) qty=qty or 1; local ok,e=FishHookMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then FishHookMaker.ironStock=FishHookMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then FishHookMaker.bronzeStock=FishHookMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then FishHookMaker.woodStock=FishHookMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FishHookMaker.leatherStock=FishHookMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FishHookMaker.silverStock=FishHookMaker.silverStock-d.silverCost*qty end; if d.goldCost then FishHookMaker.goldStock=FishHookMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FishHookMaker.jewelStock=FishHookMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FishHookMaker.pearlStock=FishHookMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FishHookMaker.maker then t=math.max(1,t-math.floor(FishHookMaker.maker.skill/13)) end; table.insert(FishHookMaker.activeMaking,{id="fishhook_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FishHookMaker.completeMaking(m) local q=1.0+(FishHookMaker.getQualityBonus()/100); if FishHookMaker.maker then q=q+(FishHookMaker.maker.skill/140) end; q=math.min(2.5,q); FishHookMaker.productStock[m.productType]=(FishHookMaker.productStock[m.productType] or 0)+m.quantity; FishHookMaker.totalProducts=FishHookMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FishHookMaker.maker then FishHookMaker.maker.itemsMade=FishHookMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FishHookMaker.maker.skill=math.min(100,FishHookMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kavka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fishhook.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function FishHookMaker.update(dt) if not _G.state then return end; FishHookMaker.dayTimer=FishHookMaker.dayTimer+dt; if FishHookMaker.dayTimer>=30 then FishHookMaker.dayTimer=0; for i=#FishHookMaker.activeMaking,1,-1 do local m=FishHookMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FishHookMaker.completeMaking(m); table.remove(FishHookMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FishHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FishHookMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FishHookMaker.getStats() return {ironStock=FishHookMaker.ironStock,bronzeStock=FishHookMaker.bronzeStock,woodStock=FishHookMaker.woodStock,leatherStock=FishHookMaker.leatherStock,silverStock=FishHookMaker.silverStock,goldStock=FishHookMaker.goldStock,jewelStock=FishHookMaker.jewelStock,pearlStock=FishHookMaker.pearlStock,productStock=FishHookMaker.productStock,numBuildings=#FishHookMaker.buildings,hasMaker=FishHookMaker.maker~=nil,makerName=FishHookMaker.maker and FishHookMaker.maker.name or "—",makerSkill=FishHookMaker.maker and FishHookMaker.maker.skill or 0,activeMaking=#FishHookMaker.activeMaking,totalProducts=FishHookMaker.totalProducts} end
return FishHookMaker
